using System;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Media;
partial class TerminalWindow {
 static string PaletteScopeLabel(string key){return key=="download"?"下载":key=="upload"?"上传":key=="cpuTemp"?"CPU温度":key=="gpuTemp"?"GPU温度":MonitorEngine.Label(key);}
 static double TaskbarSliderMaximum(string caption,double maximum){if(caption.StartsWith("水平偏移"))return 200;if(caption.StartsWith("宽度上限"))return 600;if(caption.StartsWith("高度上限"))return 64;if(caption.Contains("数值宽度"))return 140;if(caption.StartsWith("列与列间隔"))return 32;if(caption.StartsWith("两行上下间距"))return 16;if(caption.StartsWith("标签与数值间距"))return 24;if(caption.Contains("侧留白"))return 24;if(caption.Contains("部留白"))return 12;return maximum;}
 static ControlTemplate TaskbarItemToggleTemplate(){return (ControlTemplate)System.Windows.Markup.XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='CheckBox'><Grid Background='Transparent'><Grid.ColumnDefinitions><ColumnDefinition Width='*'/><ColumnDefinition Width='34'/></Grid.ColumnDefinitions><ContentPresenter VerticalAlignment='Center' Margin='0,0,5,0'/><Border x:Name='Track' Grid.Column='1' Height='22' CornerRadius='11' Background='{DynamicResource DeskTrack}'><Ellipse x:Name='Thumb' Width='16' Height='16' Fill='White' HorizontalAlignment='Left' Margin='3,0,0,0'/></Border></Grid><ControlTemplate.Triggers><Trigger Property='IsChecked' Value='True'><Setter TargetName='Track' Property='Background' Value='{DynamicResource DeskAccent}'/><Setter TargetName='Thumb' Property='HorizontalAlignment' Value='Right'/><Setter TargetName='Thumb' Property='Margin' Value='0,0,3,0'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='Track' Property='BorderBrush' Value='{DynamicResource DeskText}'/><Setter TargetName='Track' Property='BorderThickness' Value='1'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.4'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");}
 static TextBox TaskbarFontSize(Panel parent,string language,double size){var box=TaskbarInput(parent,language+"字号（7–24 pt）",size.ToString(System.Globalization.CultureInfo.InvariantCulture),62);var row=(WrapPanel)box.Parent;((TextBlock)row.Children[0]).Text="字号";((TextBlock)row.Children[0]).Width=40;foreach(int direction in new[]{-1,1}){int step=direction;var button=TaskbarName(new Button{Content=step<0?"−":"+",Width=30,MinHeight=32,FontSize=16,Padding=new Thickness(0),Margin=new Thickness(4,0,0,0),ToolTip="每次调整0.5 pt，范围7–24 pt"},language+"字号"+(step<0?"减小":"增加"));button.Click+=(o,e)=>{double value;if(Double.TryParse(box.Text,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out value)&&!Double.IsNaN(value)&&!Double.IsInfinity(value))box.Text=Math.Max(7,Math.Min(24,value+step*.5)).ToString(System.Globalization.CultureInfo.InvariantCulture);};row.Children.Add(button);}return box;}
 static Grid SettingsPair(UIElement left,UIElement right,string name){DetachSetting(left);DetachSetting(right);var grid=TaskbarName(new Grid(),name);grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition());((FrameworkElement)left).Margin=new Thickness(0,0,7,12);((FrameworkElement)right).Margin=new Thickness(7,0,0,12);Grid.SetColumn(right,1);grid.Children.Add(left);grid.Children.Add(right);return grid;}
 static Border FontSection(string title,TextBox face,TextBox size,CheckBox bold,CheckBox italic){var fontRow=(WrapPanel)face.Parent;((TextBlock)fontRow.Children[0]).Visibility=Visibility.Collapsed;face.Width=145;var pick=fontRow.Children.OfType<Button>().First();pick.Content="选择字体…";pick.Padding=new Thickness(8,6,8,6);pick.Margin=new Thickness(6,0,0,0);DetachSetting(bold);DetachSetting(italic);var styles=new WrapPanel();bold.Margin=new Thickness(0,3,12,3);italic.Margin=new Thickness(0,3,0,3);styles.Children.Add(bold);styles.Children.Add(italic);return SectionFrame(title,null,fontRow,SettingRow(size),styles);}
 static ToggleButton ScopeChip(string label){var chip=new ToggleButton{Content=label,MinHeight=34,Padding=new Thickness(10,6,10,6),Margin=new Thickness(0,0,6,6),HorizontalContentAlignment=HorizontalAlignment.Center,FontSize=12};chip.SetResourceReference(Control.ForegroundProperty,"DeskText");var template=new ControlTemplate(typeof(ToggleButton));var border=new FrameworkElementFactory(typeof(Border),"Chip");border.SetValue(Border.CornerRadiusProperty,new CornerRadius(7));border.SetValue(Border.PaddingProperty,new Thickness(10,7,10,7));border.SetValue(Border.BorderThicknessProperty,new Thickness(1));border.SetResourceReference(Border.BackgroundProperty,"DeskBase");border.SetResourceReference(Border.BorderBrushProperty,"DeskLine");var content=new FrameworkElementFactory(typeof(ContentPresenter));content.SetValue(FrameworkElement.HorizontalAlignmentProperty,HorizontalAlignment.Center);content.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);border.AppendChild(content);template.VisualTree=border;var active=new Trigger{Property=ToggleButton.IsCheckedProperty,Value=true};active.Setters.Add(new Setter(Border.BackgroundProperty,new DynamicResourceExtension("DeskSelected"),"Chip"));active.Setters.Add(new Setter(Border.BorderBrushProperty,new DynamicResourceExtension("DeskAccent"),"Chip"));template.Triggers.Add(active);var hover=new Trigger{Property=UIElement.IsMouseOverProperty,Value=true};hover.Setters.Add(new Setter(Border.BorderBrushProperty,new DynamicResourceExtension("DeskAccent"),"Chip"));template.Triggers.Add(hover);var disabled=new Trigger{Property=UIElement.IsEnabledProperty,Value=false};disabled.Setters.Add(new Setter(UIElement.OpacityProperty,.45));template.Triggers.Add(disabled);chip.Template=template;return chip;}
 static void DetachSetting(UIElement element){var old=LogicalTreeHelper.GetParent(element) as Panel;if(old!=null)old.Children.Remove(element);else{var decorator=LogicalTreeHelper.GetParent(element) as Decorator;if(decorator!=null)decorator.Child=null;}}
 static Border SectionFrame(string title,string hint,params UIElement[] elements){var body=new StackPanel();body.Children.Add(new TextBlock{Text=title,FontSize=14,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,10)});if(!String.IsNullOrEmpty(hint))SettingDescription(body,hint);foreach(var element in elements){DetachSetting(element);body.Children.Add(element);}var frame=new Border{Child=body,Padding=new Thickness(14),Margin=new Thickness(0,0,0,12),CornerRadius=new CornerRadius(10),BorderThickness=new Thickness(1),Tag="theme-art"};frame.SetResourceReference(Border.BackgroundProperty,"DeskBase");frame.SetResourceReference(Border.BorderBrushProperty,"DeskLine");return frame;}
 static void CompactLayoutRows(DependencyObject element){var grid=element as Grid;if(grid!=null&&grid.Children.Count>=3&&grid.Children[0] is TextBlock&&grid.Children[1] is StackPanel&&grid.Children[2] is TextBox){grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.ColumnDefinitions[0].Width=new GridLength(1,GridUnitType.Star);grid.ColumnDefinitions[1].Width=new GridLength(0);grid.ColumnDefinitions[2].Width=new GridLength(72);var label=(TextBlock)grid.Children[0];label.Text=label.Text.Split('（')[0];label.Margin=new Thickness(0,0,0,4);Grid.SetColumnSpan(label,grid.Children.Count>3?2:3);Grid.SetColumn(grid.Children[1],0);Grid.SetColumnSpan(grid.Children[1],2);Grid.SetRow(grid.Children[1],1);Grid.SetRow(grid.Children[2],1);if(grid.Children.Count>3){var check=(CheckBox)grid.Children[3];grid.Children.Remove(check);var chip=ScopeChip("独立");chip.IsChecked=check.IsChecked;chip.Margin=new Thickness(0,0,0,4);System.Windows.Automation.AutomationProperties.SetName(chip,System.Windows.Automation.AutomationProperties.GetName(check));Grid.SetColumn(chip,2);grid.Children.Add(chip);chip.Click+=(s,e)=>{check.IsChecked=chip.IsChecked;check.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));};check.Checked+=(s,e)=>chip.IsChecked=true;check.Unchecked+=(s,e)=>chip.IsChecked=false;grid.ColumnDefinitions.RemoveAt(3);}var slider=((StackPanel)grid.Children[1]).Children.OfType<Slider>().First();slider.ToolTip="滑块常用范围 "+slider.Minimum+"–"+slider.Maximum+"；数字框可输入完整允许范围。";}
  var wrap=element as WrapPanel;if(wrap!=null&&wrap.Children.Count==2&&wrap.Children[0] is TextBlock&&wrap.Children[1] is ComboBox){var label=(TextBlock)wrap.Children[0];label.Width=Double.NaN;label.Margin=new Thickness(0,0,0,6);wrap.Orientation=Orientation.Vertical;var choice=(ComboBox)wrap.Children[1];choice.Width=Double.NaN;choice.HorizontalAlignment=HorizontalAlignment.Stretch;}
  foreach(var child in LogicalTreeHelper.GetChildren(element).OfType<DependencyObject>().ToArray())CompactLayoutRows(child);
 }
 static void BuildTaskbarLayoutColumns(StackPanel page,Border[] left,Border[] right,Button[] shortcuts){page.Children.Clear();var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition());page.Children.Add(grid);var first=new StackPanel{Margin=new Thickness(0,0,7,0)};var second=new StackPanel{Margin=new Thickness(7,0,0,0)};Grid.SetColumn(second,1);grid.Children.Add(first);grid.Children.Add(second);foreach(var section in left)first.Children.Add(section);foreach(var section in right)second.Children.Add(section);foreach(var button in shortcuts){DetachSetting(button);first.Children.Add(button);}CompactLayoutRows(grid);System.Windows.Automation.AutomationProperties.SetName(grid,"布局双列分组");}
}
